int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t max_pairs) {
    size_t num_pairs = 0;
    const char *start = in;

    while (num_pairs < max_pairs) {
        const char *eq = strchr(start, '=');
        if (!eq) break;
        size_t klen = (size_t)(eq - start);
        keys[num_pairs] = malloc(klen + 1);
        if (!keys[num_pairs]) return -1;
        strncpy(keys[num_pairs], start, klen);
        keys[num_pairs][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') val_start++; // Skip leading spaces

        if (*val_start == '"') {
            const char *end_quote = strchr(val_start + 1, '"');
            if (end_quote) {
                size_t vlen = (size_t)(end_quote - val_start) - 1;
                vals[num_pairs] = malloc(vlen + 1);
                if (!vals[num_pairs]) {
                    for (size_t i = 0; i <= num_pairs; ++i) free(keys[i]);
                    return -1;
                }
                strncpy(vals[num_pairs], val_start + 1, vlen);
                vals[num_pairs][vlen] = '\0';
                start = end_quote + 1;
            } else {
                for (size_t i = 0; i <= num_pairs; ++i) free(keys[i]);
                return -1;
            }
        } else {
            const char *space = strchr(val_start, ' ');
            if (!space) space = eq + strlen(eq); // End of string or next equals sign
            size_t vlen = (size_t)(space - val_start);
            vals[num_pairs] = malloc(vlen + 1);
            if (!vals[num_pairs]) {
                for (size_t i = 0; i <= num_pairs; ++i) free(keys[i]);
                return -1;
            }
